#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

typedef uint64_t u64;
static u64 s[4];

static u64 rotl(u64 x, int n){ return (x<<n) | (x>>(64-n)); }

static u64 nextrand(void){
  u64 s0=s[0], s1=s[1], s2=s[2]^s0, s3=s[3]^s1;
  u64 res = rotl(s1*5, 7) * 9;
  s[0] = s0 ^ s3;
  s[1] = s1 ^ s2;
  s[2] = s2 ^ (s1 << 17);
  s[3] = rotl(s3, 45);
  return res;
}

static void setseed(u64 n1, u64 n2){
  s[0]=n1; s[1]=0xff; s[2]=n2; s[3]=0;
  for(int i=0;i<16;i++) nextrand();
}

static double I2d(u64 x){ return (double)(x >> 11) * (0.5/ ((u64)1<<52)); } /* 2^-53 */

static u64 project(u64 ran, u64 n){
  if ((n & (n+1)) == 0) return ran & n;
  u64 lim = n;
  lim |= lim>>1; lim |= lim>>2; lim |= lim>>4; lim |= lim>>8; lim |= lim>>16; lim |= lim>>32;
  while ((ran &= lim) > n) ran = nextrand();
  return ran;
}

int main(int argc, char**argv){
  /* argv[1]=mode argv[2]=seed argv[3]=count [argv[4]=low argv[5]=up] */
  const char*mode=argv[1];
  long long seed=atoll(argv[2]);
  int cnt=atoi(argv[3]);
  setseed((u64)seed, 0);
  for(int i=0;i<cnt;i++){
    u64 rv=nextrand();
    if(!strcmp(mode,"f")) printf("%.17g\n", I2d(rv));
    else if(!strcmp(mode,"i0")) printf("%lld\n", (long long)rv);
    else {
      long long low=atoll(argv[4]), up=atoll(argv[5]);
      u64 p = project(rv, (u64)up - (u64)low);
      printf("%lld\n", (long long)(p + (u64)low));
    }
  }
  return 0;
}
